      es: ["Alberga tumbas de cuatro reyes aqueménidas", "Las tumbas están excavadas en una pared rocosa", "Importantes relieves rupestres sasánidas", "Situado cerca de Persépolis"],
      pt: ["Abriga túmulos de quatro reis aqueménidas", "Os túmulos estão escavados numa parede rochosa", "Importantes relevos rupestres sassânidas", "Situado perto de Persépolis"],
